// Typing effect for the title
function typeEffect(element, text, speed = 100) {
    let i = 0;
    element.innerHTML = '';
    const timer = setInterval(() => {
        if (i < text.length) {
            element.innerHTML += text.charAt(i);
            i++;
        } else {
            clearInterval(timer);
        }
    }, speed);
}

// Initialize system sounds
const initializeSound = new Audio('data:audio/wav;base64,');

// Boot up sequence text
const bootSequence = [
    "Initializing JARVIS core systems...",
    "Loading security protocols...",
    "Establishing neural networks...",
    "Calibrating interface..."
];

// Add system startup sounds
function playSystemSound() {
    initializeSound.play();
}

// Simulate loading with progress messages
function simulateLoading(messages, callback) {
    let i = 0;
    const loadingElement = document.createElement('div');
    loadingElement.className = 'loading-messages';
    document.querySelector('.payment-card').appendChild(loadingElement);

    const interval = setInterval(() => {
        if (i < messages.length) {
            playSystemSound();
            loadingElement.innerHTML += `<div class="message">${messages[i]}</div>`;
            i++;
        } else {
            clearInterval(interval);
            setTimeout(() => {
                loadingElement.remove();
                if (callback) callback();
            }, 1000);
        }
    }, 1000);
}

// Form submission handler
document.getElementById('paymentForm').addEventListener('submit', function(e) {
    e.preventDefault();
    
    const accessId = document.getElementById('email').value;
    const securityCode = document.getElementById('password').value;
    
    // Disable form during loading
    const form = this;
    form.style.opacity = '0.5';
    form.style.pointerEvents = 'none';

    // Simulate system initialization
    simulateLoading(bootSequence, () => {
        // Re-enable form
        form.style.opacity = '1';
        form.style.pointerEvents = 'auto';
        
        // Show access message
        alert(`Access granted: Welcome back, User ${accessId}`);
    });
});

// Request access button handler
document.querySelector('.signup-btn').addEventListener('click', function() {
    playSystemSound();
    alert('Initiating new user registration protocol...');
});

// Initialize page effects
document.addEventListener('DOMContentLoaded', function() {
    // Type out the title
    const title = document.querySelector('h2');
    typeEffect(title, "JARVIS INTERFACE");
    
    // Add hover sound effects to buttons
    document.querySelectorAll('button').forEach(button => {
        button.addEventListener('mouseenter', playSystemSound);
    });
});

// Add input field effects
document.querySelectorAll('input').forEach(input => {
    input.addEventListener('focus', () => {
        playSystemSound();
    });
});